export function createCityMusic(){
 window.__disposeCityMusic?.();
 const audio=new Audio();audio.volume=0;audio.preload='auto';audio.loop=true;audio.playsInline=true;audio.dataset.cityMusic='';audio.hidden=true;document.body.append(audio);
 const controller=new AbortController();let configuredVolume=.05,renderedVolume=1,context=null,volumeNode=null,mediaNode=null,currentMultiplier=0;let wanted=false,disposed=false,starting=false,failed=false,lastAttempt=0;const voices=new Set();
 function connectVolume(){if(context||disposed)return;const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;try{context=new AudioContext();volumeNode=context.createGain();volumeNode.gain.value=currentMultiplier;mediaNode=context.createMediaElementSource(audio);mediaNode.connect(volumeNode);volumeNode.connect(context.destination);audio.volume=1;}catch{context?.close().catch(()=>{});context=null;volumeNode=null;mediaNode=null;}}
 const syncVoice=event=>{const voice=event.target;if(voice?.dataset?.mentorVoice!=='1')return;if(event.type==='playing')voices.add(voice);else voices.delete(voice);};
 for(const event of ['playing','pause','ended','waiting','emptied','error'])document.addEventListener(event,syncVoice,{capture:true,signal:controller.signal});
 async function start(){if(disposed||failed||!wanted||!audio.src||starting||!audio.paused||document.hidden||(lastAttempt>0&&performance.now()-lastAttempt<3000))return;starting=true;lastAttempt=performance.now();try{connectVolume();if(context?.state==='suspended')void context.resume().catch(()=>{});await audio.play();audio.dataset.state='playing';}catch(e){audio.dataset.state=e.name==='NotAllowedError'?'gesture-required':'unavailable';}finally{starting=false;}}
 fetch('/assets/arrival/pingtan.json?v=126',{signal:controller.signal,cache:'no-store'}).then(r=>r.json()).then(c=>{if(disposed||!c.url)return;const volume=Number(c.volume);configuredVolume=Number.isFinite(volume)?Math.max(0,Math.min(.5,volume)):.05;renderedVolume=Number(c.renderedVolume)>0?Number(c.renderedVolume):1;audio.src=c.url;audio.dataset.renderedVolume=String(renderedVolume);audio.load();void start();}).catch(()=>{});
 audio.addEventListener('error',()=>{failed=true;audio.dataset.state='unavailable';});
 const unlock=()=>{lastAttempt=0;connectVolume();if(context?.state==='suspended')void context.resume().catch(()=>{});if(!wanted&&audio.src){const wasMuted=audio.muted;audio.muted=true;void audio.play().then(()=>{if(!wanted)audio.pause();audio.muted=wasMuted;}).catch(()=>{audio.muted=wasMuted;});}else void start();};for(const event of ['pointerdown','touchend'])document.addEventListener(event,unlock,{capture:true,signal:controller.signal});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)audio.pause();else void start();},{signal:controller.signal});
 function dispose(){if(disposed)return;disposed=true;controller.abort();voices.clear();audio.pause();mediaNode?.disconnect();volumeNode?.disconnect();context?.close().catch(()=>{});audio.removeAttribute('src');audio.load();audio.remove();if(window.__disposeCityMusic===dispose)delete window.__disposeCityMusic;}window.__disposeCityMusic=dispose;
 return {stop(){wanted=false;audio.pause();currentMultiplier=0;if(volumeNode)volumeNode.gain.value=0;else audio.volume=0;},update(active,dt){for(const voice of voices)if(!voice.isConnected||voice.paused||voice.ended)voices.delete(voice);wanted=Number(active)>0;const gain=voices.size?.3:1,target=configuredVolume*Math.max(0,Math.min(1,Number(active)))*gain,multiplier=Math.min(1,target/renderedVolume);audio.dataset.ducked=String(voices.size>0);audio.dataset.targetVolume=String(target);currentMultiplier+=(multiplier-currentMultiplier)*(1-Math.exp(-Math.max(0,dt)*(multiplier<currentMultiplier?12:3)));if(volumeNode){volumeNode.gain.setTargetAtTime(currentMultiplier,context.currentTime,.025);audio.volume=1;}else audio.volume=currentMultiplier;audio.dataset.effectiveVolume=String(currentMultiplier*renderedVolume);if(wanted)void start();else if(currentMultiplier*renderedVolume<.003)audio.pause();},dispose};
}
